package net.civeira.phylax.features.document.snippet.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.snippet.domain.Snippet;
import net.civeira.phylax.features.document.snippet.domain.gateway.SnippetCursor;
import net.civeira.phylax.features.document.snippet.domain.gateway.SnippetFilter;

class SnippetSlider extends Slider<Snippet> {

  /**
   * @autogenerated SlideGenerator
   */
  private final SnippetCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final SnippetFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<SnippetFilter, SnippetCursor, Iterator<Snippet>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  SnippetSlider(final Iterator<Snippet> multi, final int limit,
      final BiFunction<SnippetFilter, SnippetCursor, Iterator<Snippet>> gateway,
      final SnippetFilter filter, final SnippetCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param snippets
   * @param limit
   * @return
   */
  @Override
  public Iterator<Snippet> next(List<Snippet> snippets, int limit) {
    Snippet last = snippets.get(snippets.size() - 1);
    SnippetCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
